// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon } from 'lucide-react'

import {
  BrowserChrome,
  DemoStage,
  DockHeader,
  MockPage,
  mockImage,
  type Build,
} from '@/app/demos/stage'

import { ACTIONS, CAPTIONS, COVERED, IMAGES, MARKDOWN, PICKED, STATS } from './script'

const TILE = 104
const COLUMNS = [
  IMAGES.map((_, index) => index).filter((index) => index % 2 === 0),
  IMAGES.map((_, index) => index).filter((index) => index % 2 === 1),
]
const MISSING = IMAGES.map((image, index) => (image.alt === null ? index : -1)).filter(
  (index) => index >= 0,
)

const build: Build = ({
  tl,
  q,
  qa,
  step,
  final,
  move,
  click,
  count,
  fly,
  type,
  wait,
  cursorOut,
}) => {
  step(0)
  IMAGES.forEach((_, index) => {
    const at = index === 0 ? 0.4 : '<0.2'
    fly(
      `ghost-${index}`,
      q('page').querySelectorAll('[data-d="page-img"]')[index],
      `tile-${index}`,
      { at, duration: 0.7, lift: 40, scale: 1.25 },
    )
    tl.to(q(`ghost-${index}`), { opacity: 0, duration: 0.12 }, '>-0.08')
    tl.fromTo(
      q(`tile-${index}`),
      { opacity: 0, scale: 0.9 },
      { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(2)' },
      '<',
    )
    tl.to(
      q('page').querySelectorAll('[data-d="page-img"]')[index],
      { opacity: 0.25, duration: 0.2 },
      '<-0.5',
    )
  })
  count('stat-images', STATS.images, { at: '<', duration: 0.6 })

  step(1, '+=0.4')
  tl.fromTo(qa('alt'), { opacity: 0, y: 4 }, { opacity: 1, y: 0, duration: 0.25, stagger: 0.08 })
  ;(['missing', 'withAlt', 'decorative'] as const).forEach((key) =>
    count(`stat-${key}`, STATS[key], { at: '<', duration: 0.6 }),
  )
  tl.fromTo(
    q('cover-bar'),
    { scaleX: 0 },
    { scaleX: COVERED / IMAGES.length, duration: 0.8, ease: 'power3.out' },
    '<',
  )
  count('cover', COVERED, { at: '<', duration: 0.8 })

  step(2, '+=0.4')
  move('filter')
  click('filter')
  tl.to(
    q('filter'),
    {
      backgroundColor: 'rgba(251,113,133,0.18)',
      borderColor: 'rgba(251,113,133,0.6)',
      color: '#fda4af',
      duration: 0.2,
    },
    '<',
  )
  type('filter-text', 'Missing', { at: '<', speed: 0.02 })
  tl.to(
    IMAGES.map((_, index) => q(`tile-${index}`)).filter((_, index) => !MISSING.includes(index)),
    { opacity: 0.35, scale: 0.96, duration: 0.3 },
    '<',
  )
  wait(0.8)
  move('filter')
  click('filter')
  tl.to(
    q('filter'),
    {
      backgroundColor: 'rgba(255,255,255,0)',
      borderColor: 'var(--demo-tint-8)',
      color: 'var(--demo-ink-soft)',
      duration: 0.2,
    },
    '<',
  )
  type('filter-text', 'Any', { at: '<', speed: 0.02 })
  tl.to(qa('tile'), { opacity: 1, scale: 1, duration: 0.3 }, '<')

  step(3, '+=0.3')
  move(`tile-${PICKED}`, { ay: 0.4 })
  tl.fromTo(q('actions'), { opacity: 0, y: 4 }, { opacity: 1, y: 0, duration: 0.2 }, '>-0.1')
  move('action-3')
  click('action-3')
  tl.fromTo(
    q('toast'),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'back.out(2)' },
    '<',
  )
  tl.to(q('actions'), { opacity: 0, duration: 0.2 }, '+=0.4')
  tl.to(q('page').querySelectorAll('[data-d="page-img"]'), { opacity: 1, duration: 0.25 }, '<')
  cursorOut('<')
  final()
  wait(1.4)
}

export default function Demo() {
  return (
    <DemoStage
      label="Image Links lifting a page’s images into a grid, auditing alt text and copying one as Markdown"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://northwind.app/new"
        panelWidth={240}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="relative flex min-h-0 flex-1 flex-col gap-1.5 p-2">
              <div className="grid grid-cols-4 gap-1">
                {(
                  [
                    ['images', 'Images'],
                    ['missing', 'Missing alt'],
                    ['withAlt', 'With alt'],
                    ['decorative', 'Decorative'],
                  ] as const
                ).map(([key, label]) => (
                  <div
                    key={key}
                    className="rounded-md border border-line bg-canvas/60 py-0.5 text-center"
                  >
                    <p
                      data-d={`stat-${key}`}
                      className="text-[11px] font-semibold tabular-nums"
                      style={{ color: key === 'missing' ? '#fb7185' : 'var(--demo-ink)' }}
                    >
                      0
                    </p>
                    <p className="truncate text-[7.5px] text-muted">{label}</p>
                  </div>
                ))}
              </div>
              <div className="flex items-center gap-1.5">
                <div className="h-1 flex-1 overflow-hidden rounded-full bg-ink/10">
                  <div
                    data-d="cover-bar"
                    className="h-full origin-left scale-x-0 rounded-full bg-[var(--accent)]"
                  />
                </div>
                <span className="text-[8.5px] text-muted">
                  <span data-d="cover">0</span> of {IMAGES.length} &lt;img&gt;
                </span>
                <span
                  data-d="filter"
                  className="rounded-full border border-line px-1.5 py-0.5 text-[8.5px] text-ink-soft"
                >
                  <span data-d="filter-text">Any</span>
                </span>
              </div>
              <div className="flex gap-1.5">
                {COLUMNS.map((column, columnIndex) => (
                  <div key={columnIndex} className="flex flex-col gap-1.5" style={{ width: TILE }}>
                    {column.map((index) => {
                      const image = IMAGES[index]
                      return (
                        <div
                          key={index}
                          data-d={`tile tile-${index}`}
                          className="relative overflow-hidden rounded-md opacity-0"
                          style={{
                            height: Math.round(((TILE * image.height) / image.width) * 0.68),
                            background: mockImage(index + 1),
                          }}
                        >
                          <span
                            data-d="alt"
                            className="absolute left-1 top-1 rounded px-1 text-[7.5px] font-medium opacity-0"
                            style={{
                              color: image.alt === null ? '#fff1f2' : '#0b0b11',
                              backgroundColor:
                                image.alt === null
                                  ? '#be123c'
                                  : image.alt === ''
                                    ? '#c9c9d3'
                                    : '#34d399',
                            }}
                          >
                            {image.alt === null
                              ? 'No alt'
                              : image.alt === ''
                                ? 'Decorative'
                                : 'Alt'}
                          </span>
                          <span className="absolute inset-x-0 bottom-0 bg-black/45 px-1 py-px font-mono text-[7.5px] text-white">
                            {image.width}×{image.height}
                          </span>
                          {index === PICKED ? (
                            <div
                              data-d="actions"
                              className="absolute inset-x-1 top-5 space-y-px rounded-md border border-line-strong bg-elevated p-0.5 opacity-0 shadow-xl"
                            >
                              {ACTIONS.map((action, actionIndex) => (
                                <p
                                  key={action}
                                  data-d={`action-${actionIndex}`}
                                  className="rounded px-1 py-px text-[8px] text-ink-soft"
                                >
                                  {action}
                                </p>
                              ))}
                            </div>
                          ) : null}
                        </div>
                      )
                    })}
                  </div>
                ))}
              </div>
              <div
                data-d="toast"
                className="absolute inset-x-2 bottom-2 rounded-md border border-[var(--accent)]/40 bg-elevated px-2 py-1.5 opacity-0 shadow-xl"
              >
                <p className="flex items-center gap-1 text-[9px] font-medium text-ink">
                  <CheckIcon className="size-2.5 text-[var(--accent)]" /> Copied Markdown
                </p>
                <p className="truncate font-mono text-[8px] text-muted">{MARKDOWN}</p>
              </div>
            </div>
          </div>
        }
      >
        <MockPage variant="shop" />
      </BrowserChrome>
      {IMAGES.map((_, index) => (
        <div
          key={index}
          data-d={`ghost-${index}`}
          className="absolute left-0 top-0 z-30 h-14 w-[76px] rounded-md opacity-0 shadow-2xl"
          style={{ background: mockImage(index + 1) }}
        />
      ))}
    </DemoStage>
  )
}
